package com.scriptles.cabinet.profile.repository;
import com.scriptles.cabinet.profile.entity.ProfileFollow; import com.scriptles.cabinet.profile.entity.Profile; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface ProfileFollowRepository extends JpaRepository<ProfileFollow,UUID> { boolean existsByFollowerIdAndFollowedId(UUID follower,UUID followed); void deleteByFollowerIdAndFollowedId(UUID follower,UUID followed); long countByFollowedId(UUID id); long countByFollowerId(UUID id); @Query("select f.follower from ProfileFollow f where f.followed.id=:id order by f.createdAt desc") Page<Profile> followers(@Param("id") UUID id,Pageable page); @Query("select f.followed from ProfileFollow f where f.follower.id=:id order by f.createdAt desc") Page<Profile> following(@Param("id") UUID id,Pageable page); }
